import json
from openai import OpenAI
client = OpenAI()

# STEP 1: Define your tools (functions the LLM can choose to call)
tools = [
    {
        "type": "function",
        "function": {
            "name": "get_weather",
            "description": "Get current weather for a city",
            "parameters": {
                "type": "object",
                "properties": {
                    "city": {
                        "type": "string",
                        "description": "The city name, e.g. 'Mumbai'"
                    },
                    "unit": {
                        "type": "string",
                        "enum": ["celsius", "fahrenheit"]
                    }
                },
                "required": ["city"]
            }
        }
    },
    {
        "type": "function", 
        "function": {
            "name": "search_database",
            "description": "Search the company product database",
            "parameters": {
                "type": "object",
                "properties": {
                    "query": {"type": "string"},
                    "limit": {"type": "integer", "default": 10}
                },
                "required": ["query"]
            }
        }
    }
]

# STEP 2: Your actual functions
def get_weather(city, unit="celsius"):
    # In real code, call an actual weather API!
    return {"city": city, "temp": 32, "condition": "Sunny"}

def search_database(query, limit=10):
    # In real code, query your actual database!
    return {"results": ["Product A", "Product B"]}

# STEP 3: Send message with tools to LLM
messages = [{"role": "user", "content": "What's the weather in Mumbai?"}]

response = client.chat.completions.create(
    model="gpt-4",
    messages=messages,
    tools=tools,
    tool_choice="auto"  # Let LLM decide when to use tools
)

# STEP 4: Check if LLM wants to call a function
if response.choices[0].finish_reason == "tool_calls":
    tool_call = response.choices[0].message.tool_calls[0]
    function_name = tool_call.function.name  # "get_weather"
    arguments = json.loads(tool_call.function.arguments)  # {"city": "Mumbai"}

    # STEP 5: Execute the function yourself
    if function_name == "get_weather":
        result = get_weather(**arguments)

    # STEP 6: Send result back to LLM for final response
    messages.append(response.choices[0].message)
    messages.append({
        "role": "tool",
        "tool_call_id": tool_call.id,
        "content": json.dumps(result)
    })

    final_response = client.chat.completions.create(
        model="gpt-4",
        messages=messages,
        tools=tools
    )
    print(final_response.choices[0].message.content)
    # "The current weather in Mumbai is 32°C and sunny!"
